import java.util.Arrays;

public class Main {
    static long[] t;
    // Each node k stores the sum of its range [l, r]
    static void build(int[] a, int k, int l, int r) {
        if (l == r) { t[k] = a[l]; return; }
        int m = (l + r) / 2;
        build(a, 2 * k, l, m);
        build(a, 2 * k + 1, m + 1, r);
        t[k] = t[2 * k] + t[2 * k + 1];
    }
    // Point update: walk down to one leaf, then fix the sums on the way back
    static void update(int k, int l, int r, int i, int v) {
        if (l == r) { t[k] = v; return; }
        int m = (l + r) / 2;
        if (i <= m) update(2 * k, l, m, i, v); else update(2 * k + 1, m + 1, r, i, v);
        t[k] = t[2 * k] + t[2 * k + 1];
    }
    static long query(int k, int l, int r, int ql, int qr) {
        if (qr < l || r < ql) return 0;          // no overlap: identity for sum
        if (ql <= l && r <= qr) return t[k];     // fully inside: use stored sum
        int m = (l + r) / 2;
        return query(2 * k, l, m, ql, qr) + query(2 * k + 1, m + 1, r, ql, qr);
    }
    public static void main(String[] args) {
        int[] a = {2, 1, 5, 3, 4};
        int n = a.length;
        t = new long[4 * n];
        build(a, 1, 0, n - 1);
        System.out.println("a = " + Arrays.toString(a));
        System.out.println("sum(1..3) = " + query(1, 0, n - 1, 1, 3));
        update(1, 0, n - 1, 2, 10);
        System.out.println("set a[2] = 10");
        System.out.println("sum(1..3) = " + query(1, 0, n - 1, 1, 3));
        System.out.println("sum(0..4) = " + query(1, 0, n - 1, 0, 4));
        // Time: build O(N), update and query O(log N). Space: O(N) (4N cells).
    }
}

