import java.util.Arrays;

public class Main {
    static long[] sum, lazy;
    // Fully covered node: fix its sum now, remember what the children still owe
    static void apply(int k, int len, long v) { sum[k] += v * len; lazy[k] += v; }
    // Push the pending tag to both children before going below this node
    static void push(int k, int l, int r) {
        if (lazy[k] == 0) return;
        int m = (l + r) / 2;
        apply(2 * k, m - l + 1, lazy[k]);
        apply(2 * k + 1, r - m, lazy[k]);
        lazy[k] = 0;
    }
    static void add(int k, int l, int r, int ql, int qr, long v) {
        if (qr < l || r < ql) return;
        if (ql <= l && r <= qr) { apply(k, r - l + 1, v); return; }
        push(k, l, r);
        int m = (l + r) / 2;
        add(2 * k, l, m, ql, qr, v);
        add(2 * k + 1, m + 1, r, ql, qr, v);
        sum[k] = sum[2 * k] + sum[2 * k + 1];   // pull: rebuild from children
    }
    static long query(int k, int l, int r, int ql, int qr) {
        if (qr < l || r < ql) return 0;
        if (ql <= l && r <= qr) return sum[k];
        push(k, l, r);
        int m = (l + r) / 2;
        return query(2 * k, l, m, ql, qr) + query(2 * k + 1, m + 1, r, ql, qr);
    }
    public static void main(String[] args) {
        int[] a = {1, 2, 3, 4, 5, 6};
        int n = a.length;
        sum = new long[4 * n];
        lazy = new long[4 * n];
        for (int i = 0; i < n; i++) add(1, 0, n - 1, i, i, a[i]);
        System.out.println("a = " + Arrays.toString(a));
        add(1, 0, n - 1, 1, 4, 10);
        System.out.println("add 10 to [1..4]");
        System.out.println("sum(0..5) = " + query(1, 0, n - 1, 0, 5));
        System.out.println("sum(2..3) = " + query(1, 0, n - 1, 2, 3));
        add(1, 0, n - 1, 3, 5, 5);
        System.out.println("add 5 to [3..5]");
        System.out.println("sum(3..5) = " + query(1, 0, n - 1, 3, 5));
        System.out.println("sum(0..2) = " + query(1, 0, n - 1, 0, 2));
        // Time: O(log N) per range update and per query. Space: O(N).
    }
}

