import java.util.Arrays;

public class Main {
    static int n;
    static long[] tree;   // 1-based, N + 1 cells
    // Add v at position i: climb to every box that covers i
    static void add(int i, long v) {
        for (; i <= n; i += i & -i) tree[i] += v;
    }
    // Sum of positions 1..i: jump down by the lowest set bit
    static long prefix(int i) {
        long s = 0;
        for (; i > 0; i -= i & -i) s += tree[i];
        return s;
    }
    // A range answer needs subtraction, so the operation must be invertible
    static long range(int l, int r) { return prefix(r) - prefix(l - 1); }

    public static void main(String[] args) {
        int[] a = {3, 2, -1, 6, 5, 4};
        n = a.length;
        tree = new long[n + 1];
        for (int i = 0; i < n; i++) add(i + 1, a[i]);
        System.out.println("a = " + Arrays.toString(a) + " (positions 1..6)");
        System.out.println("sum(2..5) = " + range(2, 5));
        add(3, 3);
        System.out.println("add 3 at position 3");
        System.out.println("sum(2..5) = " + range(2, 5));
        System.out.println("prefix(6) = " + prefix(6));
        // Time: O(log N) per add and per prefix. Space: O(N).
    }
}

