    static long[] tree;   // 1-based, N + 1 cells
    // Add v at position i: climb to every box that covers i
    static void Add(int i, long v) {
        for (; i <= n; i += i & -i) tree[i] += v;
    }
    // Sum of positions 1..i: jump down by the lowest set bit
    static long Prefix(int i) {
        long s = 0;
        for (; i > 0; i -= i & -i) s += tree[i];
        return s;
    }
    // A range answer needs subtraction, so the operation must be invertible
    static long Range(int l, int r) { return Prefix(r) - Prefix(l - 1); }

