public class Main {
    // -i is ~i + 1 in two's complement, so only the lowest 1 bit survives the AND
    static int lowbit(int i) { return i & -i; }

    public static void main(String[] args) {
        int[] samples = {12, 10, 8, 7};
        for (int i : samples) {
            System.out.println("i = " + i + " (" + Integer.toBinaryString(i) + ")  lowbit = " + lowbit(i));
        }
        // Prefix query: keep removing the lowest set bit until i becomes 0
        StringBuilder q = new StringBuilder();
        for (int i = 13; i > 0; i -= lowbit(i)) q.append(" ").append(i);
        System.out.println("prefix(13) reads cells:" + q);
        // Point update: keep adding the lowest set bit until i passes n
        int n = 16;
        StringBuilder u = new StringBuilder();
        for (int i = 5; i <= n; i += lowbit(i)) u.append(" ").append(i);
        System.out.println("update(5) with n = 16 writes cells:" + u);
        // Each loop runs at most log2(N) + 1 times. Time: O(log N). Space: O(1).
    }
