public class Main {
    static int visited;
    // Same shape as a real query, but it only counts the nodes it enters
    static void query(int l, int r, int ql, int qr) {
        visited++;
        if (qr < l || r < ql) return;        // disjoint: stop
        if (ql <= l && r <= qr) return;      // fully covered: stop
        int m = (l + r) / 2;                 // partial: only these nodes go deeper
        query(l, m, ql, qr);
        query(m + 1, r, ql, qr);
    }
    public static void main(String[] args) {
        int[] sizes = {8, 64, 1024, 1048576};
        for (int n : sizes) {
            int log = 0;
            while ((1 << log) < n) log++;
            visited = 0;
            // [1, n-2] is a worst case: both ends cut nodes on every level
            query(0, n - 1, 1, n - 2);
            System.out.println("N = " + n + "  query [1, " + (n - 2) + "]  visited = " + visited
                + "  bound 4*log2(N)+1 = " + (4 * log + 1));
        }
        // Time: O(log N) per query, at most 4 nodes per level. Space: O(log N) stack.
    }
}

