public class Main {
    static int nodes, maxIndex;
    // Walk the same recursion as build(): root is 1, children are 2k and 2k+1
    static void walk(int k, int l, int r) {
        nodes++;
        if (k > maxIndex) maxIndex = k;
        if (l == r) return;
        int m = (l + r) / 2;
        walk(2 * k, l, m);
        walk(2 * k + 1, m + 1, r);
    }
    public static void main(String[] args) {
        int[] sizes = {5, 6, 7, 8, 9, 100, 1000};
        for (int n : sizes) {
            nodes = 0;
            maxIndex = 0;
            walk(1, 0, n - 1);
            // Only 2N-1 nodes exist, but the numbering leaves holes when N is not a power of two
            System.out.println("N = " + n + "  nodes = " + nodes + "  max index = " + maxIndex
                + "  2N = " + (2 * n) + "  4N = " + (4 * n));
        }
        // The max index is always below 4N, so an array of 4N cells is safe.
        // Time: O(N) for the walk. Space: O(log N) stack.
    }
}

