import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        int[] a = {5, 2, 4, 7, 1, 3, 6};
        int n = a.length;
        // lg[x] = floor(log2(x)), filled without floating point
        int[] lg = new int[n + 1];
        for (int i = 2; i <= n; i++) lg[i] = lg[i / 2] + 1;
        int levels = lg[n] + 1;
        // st[k][i] = min of the 2^k elements starting at i
        int[][] st = new int[levels][n];
        st[0] = a.clone();
        for (int k = 1; k < levels; k++)
            for (int i = 0; i + (1 << k) <= n; i++)
                st[k][i] = Math.min(st[k - 1][i], st[k - 1][i + (1 << (k - 1))]);

        System.out.println("a = " + Arrays.toString(a));
        int[][] queries = {{0, 3}, {2, 5}, {5, 6}, {3, 3}, {0, 6}};
        for (int[] q : queries) {
            int l = q[0], r = q[1];
            int k = lg[r - l + 1];
            // Two windows of length 2^k: they overlap, which is fine because min(x, x) = x
            int ans = Math.min(st[k][l], st[k][r - (1 << k) + 1]);
            System.out.println("min(" + l + ".." + r + ") = " + ans + "  (window length " + (1 << k) + ")");
        }
        // Time: build O(N log N), query O(1). Space: O(N log N). No updates.
    }
}

