import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        int[] a = {1, 2, 1, 3, 2, 2, 4, 1};
        int[][] qs = {{0, 4}, {2, 6}, {1, 3}, {5, 7}, {0, 7}};
        int B = 3;   // block size, about sqrt(N)
        Integer[] order = new Integer[qs.length];
        for (int i = 0; i < order.length; i++) order[i] = i;
        // Sort by block of l, then by r: r only moves forward inside a block
        Arrays.sort(order, (x, y) -> qs[x][0] / B != qs[y][0] / B
            ? qs[x][0] / B - qs[y][0] / B : qs[x][1] - qs[y][1]);

        int[] freq = new int[5];
        int[] ans = new int[qs.length];
        int curL = 0, curR = -1, distinct = 0, moves = 0;
        for (int id : order) {
            int l = qs[id][0], r = qs[id][1];
            // Grow the window first, then shrink it; each step is O(1)
            while (curL > l) { if (freq[a[--curL]]++ == 0) distinct++; moves++; }
            while (curR < r) { if (freq[a[++curR]]++ == 0) distinct++; moves++; }
            while (curL < l) { if (--freq[a[curL++]] == 0) distinct--; moves++; }
            while (curR > r) { if (--freq[a[curR--]] == 0) distinct--; moves++; }
            ans[id] = distinct;   // store by original index
        }
        System.out.println("a = " + Arrays.toString(a));
        for (int i = 0; i < qs.length; i++)
            System.out.println("distinct(" + qs[i][0] + ".." + qs[i][1] + ") = " + ans[i]);
        System.out.println("pointer moves = " + moves);
        // Time: O((N + Q) * sqrt(N)) plus the sort. Space: O(N + Q).
    }
}

