            while (curL < l) { if (--freq[a[curL++]] == 0) distinct--; moves++; }
            while (curR > r) { if (--freq[a[curR--]] == 0) distinct--; moves++; }
            ans[id] = distinct;   // store by original index
        }
        Console.WriteLine("a = [" + string.Join(", ", a) + "]");
        for (int i = 0; i < qs.Length; i++)
            Console.WriteLine("distinct(" + qs[i][0] + ".." + qs[i][1] + ") = " + ans[i]);
        Console.WriteLine("pointer moves = " + moves);
        // Time: O((N + Q) * sqrt(N)) plus the sort. Space: O(N + Q).
    }
}

