    static void applySet(int k, int len, long x) { sum[k] = x * len; hasSet[k] = true; setVal[k] = x; add[k] = 0; }
    static void applyAdd(int k, int len, long v) { sum[k] += v * len; add[k] += v; }
    static void push(int k, int l, int r) {
        int m = (l + r) / 2;
        // Order matters: the assignment goes down first, then the add
        if (hasSet[k]) { applySet(2 * k, m - l + 1, setVal[k]); applySet(2 * k + 1, r - m, setVal[k]); hasSet[k] = false; }
        if (add[k] != 0) { applyAdd(2 * k, m - l + 1, add[k]); applyAdd(2 * k + 1, r - m, add[k]); add[k] = 0; }
    }
    static void update(int k, int l, int r, int ql, int qr, boolean assign, long x) {
        if (qr < l || r < ql) return;
        if (ql <= l && r <= qr) {
            if (assign) applySet(k, r - l + 1, x); else applyAdd(k, r - l + 1, x);
            return;
        }
        push(k, l, r);
        int m = (l + r) / 2;
        update(2 * k, l, m, ql, qr, assign, x);
        update(2 * k + 1, m + 1, r, ql, qr, assign, x);
        sum[k] = sum[2 * k] + sum[2 * k + 1];
    }
    static long query(int k, int l, int r, int ql, int qr) {
        if (qr < l || r < ql) return 0;
        if (ql <= l && r <= qr) return sum[k];
        push(k, l, r);
        int m = (l + r) / 2;
        return query(2 * k, l, m, ql, qr) + query(2 * k + 1, m + 1, r, ql, qr);
    }
    public static void main(String[] args) {
        int[] a = {1, 2, 3, 4, 5};
