import java.util.Arrays;

public class Main {
    static int[] L, R, C;   // left child, right child, count of values in the node's rank range
    static int cnt = 0;     // node 0 is the empty tree
    // Make a new version: copy only the path to "pos", share everything else
    static int insert(int prev, int l, int r, int pos) {
        int cur = ++cnt;
        L[cur] = L[prev]; R[cur] = R[prev]; C[cur] = C[prev] + 1;
        if (l < r) {
            int m = (l + r) / 2;
            if (pos <= m) L[cur] = insert(L[prev], l, m, pos);
            else R[cur] = insert(R[prev], m + 1, r, pos);
        }
        return cur;
    }
    // Walk version u (before l) and version v (up to r) together
    static int kth(int u, int v, int l, int r, int k) {
        if (l == r) return l;
        int m = (l + r) / 2;
        int inLeft = C[L[v]] - C[L[u]];   // how many values of a[l..r] have a small rank
        if (k <= inLeft) return kth(L[u], L[v], l, m, k);
        return kth(R[u], R[v], m + 1, r, k - inLeft);
    }
    public static void main(String[] args) {
        int[] a = {3, 1, 4, 1, 5, 9, 2, 6};
        int n = a.length;
        int[] vals = Arrays.stream(a).distinct().sorted().toArray();   // rank -> value
        int m = vals.length;
        L = new int[n * 20]; R = new int[n * 20]; C = new int[n * 20];
        int[] root = new int[n + 1];
        for (int i = 0; i < n; i++)
            root[i + 1] = insert(root[i], 0, m - 1, Arrays.binarySearch(vals, a[i]));
        System.out.println("a = " + Arrays.toString(a));
        int[][] qs = {{0, 4, 2}, {2, 6, 3}, {0, 7, 5}, {5, 7, 1}};
        for (int[] q : qs) {
            int rank = kth(root[q[0]], root[q[1] + 1], 0, m - 1, q[2]);
            System.out.println("k = " + q[2] + " smallest in a[" + q[0] + ".." + q[1] + "] = " + vals[rank]);
        }
        System.out.println("nodes created = " + cnt);
        // Time: O(N log N) build, O(log N) per query. Space: O(N log N) nodes.
    }
}

