import java.util.Arrays;

public class Main {
    static long[] sum, mx;
    static int leafVisits = 0;
    static long isqrt(long x) { long r = 0; while ((r + 1) * (r + 1) <= x) r++; return r; }
    static void pull(int k) { sum[k] = sum[2 * k] + sum[2 * k + 1]; mx[k] = Math.max(mx[2 * k], mx[2 * k + 1]); }
    static void build(int[] a, int k, int l, int r) {
        if (l == r) { sum[k] = mx[k] = a[l]; return; }
        int m = (l + r) / 2;
        build(a, 2 * k, l, m); build(a, 2 * k + 1, m + 1, r);
        pull(k);
    }
    static void sqrtRange(int k, int l, int r, int ql, int qr) {
        // Prune: if every value here is 0 or 1, a square root changes nothing
        if (qr < l || r < ql || mx[k] <= 1) return;
        if (l == r) { sum[k] = mx[k] = isqrt(sum[k]); leafVisits++; return; }
        int m = (l + r) / 2;
        sqrtRange(2 * k, l, m, ql, qr); sqrtRange(2 * k + 1, m + 1, r, ql, qr);
        pull(k);
    }
