import java.util.Arrays;

public class Main {
    static int[] sorted;   // distinct coordinates in increasing order
    static int[] tree;
    // Number of stored coordinates that are smaller than x
    static int lowerBound(int x) {
        int lo = 0, hi = sorted.length;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (sorted[mid] < x) lo = mid + 1; else hi = mid;
        }
        return lo;
    }
    static void add(int i) { for (; i < tree.length; i += i & -i) tree[i]++; }
    static int prefix(int i) { int s = 0; for (; i > 0; i -= i & -i) s += tree[i]; return s; }

    public static void main(String[] args) {
        int[] xs = {1000000000, 5, 70000, 5, 123456789};
        sorted = Arrays.stream(xs).distinct().sorted().toArray();
        tree = new int[sorted.length + 1];   // size K = 4, not 10^9
        // Each point goes to its rank (1-based) instead of its raw coordinate
        for (int x : xs) add(lowerBound(x) + 1);
        System.out.println("points = " + Arrays.toString(xs));
        System.out.println("compressed = " + Arrays.toString(sorted));
        int[][] qs = {{5, 70000}, {6, 999999999}, {0, 4}, {5, 1000000000}};
        for (int[] q : qs) {
            // Query bounds need not be stored values: convert them with binary search
            int cnt = prefix(lowerBound(q[1] + 1)) - prefix(lowerBound(q[0]));
            System.out.println("points in [" + q[0] + ", " + q[1] + "] = " + cnt);
        }
        // Time: O(N log N) to compress, O(log N) per add or query. Space: O(K).
    }
}

