import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        // Latency samples; a real store would hold millions per block
        int[] a = {12, 40, 7, 33, 95, 18, 22, 5, 61, 30, 44, 9};
        int n = a.length, B = 4;
        // Precompute one summary (the max) per block, like a rollup or zone map
        int[] blockMax = new int[(n + B - 1) / B];
        for (int i = 0; i < n; i++) blockMax[i / B] = Math.max(blockMax[i / B], a[i]);

        System.out.println("a = " + Arrays.toString(a));
        System.out.println("block max (B = 4) = " + Arrays.toString(blockMax));
        int[][] queries = {{2, 10}, {0, 11}, {8, 9}, {1, 6}};
        for (int[] q : queries) {
            int l = q[0], r = q[1], best = 0, reads = 0;
            int i = l;
            while (i <= r) {
                if (i % B == 0 && i + B - 1 <= r) {
                    best = Math.max(best, blockMax[i / B]);   // whole block inside: one read
                    i += B;
                } else {
                    best = Math.max(best, a[i]);              // edge of the range: read the raw value
                    i++;
                }
                reads++;
            }
            System.out.println("max(" + l + ".." + r + ") = " + best + "  reads = " + reads
                + "  (plain scan = " + (r - l + 1) + ")");
        }
        // Time: O(N) to build, O(B + N/B) per query, about sqrt(N) when B = sqrt(N). Space: O(N/B).
    }
}

