public class Main {
    static long seed = 12345;
    // Small fixed random generator so every run (and every language) sees the same tests
    static int rnd() { seed = (seed * 75 + 74) % 65537; return (int) seed; }

    static int n;
    static int[] t;
    static final int INF = Integer.MAX_VALUE;   // identity for min, not 0
    static void update(int i, int v) {
        i += n; t[i] = v;
        while (i > 1) { i >>= 1; t[i] = Math.min(t[2 * i], t[2 * i + 1]); }
    }
    static int query(int l, int r) {   // min of a[l..r], bottom-up tree
        int res = INF;
        for (l += n, r += n + 1; l < r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1) res = Math.min(res, t[l++]);
            if ((r & 1) == 1) res = Math.min(res, t[--r]);
        }
        return res;
    }
    public static void main(String[] args) {
        int tests = 300, checks = 0, mismatches = 0;
        for (int test = 0; test < tests; test++) {
            n = 1 + rnd() % 8;                 // tiny sizes hit the edge cases
            int[] a = new int[n];
            t = new int[2 * n];
            java.util.Arrays.fill(t, INF);
            for (int i = 0; i < n; i++) { a[i] = rnd() % 100; update(i, a[i]); }
            for (int op = 0; op < 10; op++) {
                int kind = rnd() % 2, x = rnd() % n, y = rnd() % n;
                if (kind == 0) { int v = rnd() % 100; a[x] = v; update(x, v); continue; }
                int l = Math.min(x, y), r = Math.max(x, y);
