import java.util.Arrays;

public class Main {
    static int n;
    static int[] tree;
    static void add(int i, int v) { for (i++; i <= n; i += i & -i) tree[i] += v; }
    static int prefix(int i) { int s = 0; for (i++; i > 0; i -= i & -i) s += tree[i]; return s; }

    public static void main(String[] args) {
        int[] a = {1, 2, 1, 3, 2, 2, 4, 1};
        int[][] qs = {{0, 4}, {2, 6}, {1, 3}, {5, 7}, {0, 7}};
        n = a.length;
        tree = new int[n + 1];
        // Offline: answer the queries in order of their right end
        Integer[] order = new Integer[qs.length];
        for (int i = 0; i < order.length; i++) order[i] = i;
        Arrays.sort(order, (x, y) -> qs[x][1] - qs[y][1]);

        int[] last = new int[5];           // last[v] = latest index where value v was seen
        Arrays.fill(last, -1);
        int[] ans = new int[qs.length];
        int next = 0;
        for (int i = 0; i < n; i++) {
            // Keep a 1 only at the latest occurrence of each value
            if (last[a[i]] != -1) add(last[a[i]], -1);
            add(i, 1);
            last[a[i]] = i;
            // Every query ending here: count the 1s inside [l, i]
            while (next < order.length && qs[order[next]][1] == i) {
                int id = order[next++];
                ans[id] = prefix(i) - prefix(qs[id][0] - 1);
            }
        }
        System.out.println("a = " + Arrays.toString(a));
        for (int i = 0; i < qs.length; i++)
            System.out.println("distinct(" + qs[i][0] + ".." + qs[i][1] + ") = " + ans[i]);
        // Time: O((N + Q) log N). Space: O(N + Q).
    }
}

