    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int x, int y) { return qs[x].second < qs[y].second; });

    vector<int> last(5, -1);           // last[v] = latest index where value v was seen
    vector<int> ans(qs.size(), 0);
    size_t next = 0;
